with department_summary as (select dept_id, max(salary) - min(salary) as salary_range, sort_array(collect_set(level)) as level_list from employees group by dept_id) select departments.id, departments.dept_name, departments.location, department_summary.salary_range, department_summary.level_list from departments left outer join department_summary on departments.id = department_summary.dept_id where department_summary.salary_range > 28;
